export type DialogueEvent =
  | 'greeting'
  | 'idle'
  | 'buy'
  | 'sell'
  | 'farewell';

export interface ContextLine {
  zoneKeyword: string;
  lines: string[];
}

export interface NpcDialogue {
  name: string;
  location: string;
  personality: string;
  lines: Partial<Record<DialogueEvent, string[]>>;
  contextLines?: Partial<Record<DialogueEvent, ContextLine[]>>;
}

